  if (e.key === '[' || e.key === ']') {
    if (tabOrder.length < 2) return
    e.preventDefault()
    const i = tabOrder.indexOf(activeName)
    const step = e.key === ']' ? 1 : -1
    const next = tabOrder[(i + step + tabOrder.length) % tabOrder.length]
    if (next) switchTo(next)
  }
})

