/**
 * The environment of a unit test run (#werk-test-env, #werk-test-external). It keeps nothing
 * that points at a real project, a real repository or a real agent account, and it puts the
 * fake agent's folder first on PATH.
 */

/** A variable that names a real map, a real repository, or the person's agent setup. */
const REAL = /^(WERK_|CLAUDE|ANTHROPIC_|GIT_)/

export type CleanEnvInput = {
  /** The folder that holds the fake agent as `claude`. */
  fakeBin: string
  /** A fresh home folder, so no test reads the person's own configuration. */
  home: string
  /** The script file that the fake agent reads when a test passes no environment of its own. */
  agentScript: string
}

/** The environment to run every test with, built from the one the run started with. */
export function cleanEnv(env: Record<string, string | undefined>, input: CleanEnvInput): Record<string, string> {
  const out: Record<string, string> = {}
  for (const [key, value] of Object.entries(env)) {
    if (value !== undefined && !REAL.test(key)) out[key] = value
  }
  const rest = (env.PATH ?? '').split(':').filter((dir) => dir !== '' && dir !== input.fakeBin)
  out.PATH = [input.fakeBin, ...rest].join(':')
  out.HOME = input.home
  out.WERK_FAKE_AGENT_SCRIPT = input.agentScript
  return out
}
