/**
 * The text of one chat turn as the agent reads it (#werk-chat, #werk-card-blind, #werk-shot-chip).
 * A pure function of the message, the card open in the map, and the card the conversation
 * was last told about.
 *
 * The first line always names the open card, so the agent never answers about the wrong
 * subject (#werk-mc-follow). It says "now at" when the card changed since the last turn, and
 * "still on" when it did not:
 *
 *   [the map is now at #map-hash — The open card lives in the location hash]
 *   [Image #1] = /project/.werk/attachments/2026-10-23T10-00-00-000Z-1a2b3c4d.png
 *
 *   Open each image above with Read before you answer.
 *
 *   Why does a reload keep this card open?
 *
 * The first turn of a tab that opened at a card names that card, its home, on the second
 * line (#werk-mc-split). The home card is a label and a seed, not a fence: the turns after
 * it name only the open card.
 */

/** The card open in the map. The title is missing when the map has no card with the id. */
export type OpenCard = { id: string; title?: string }

export type TurnInput = {
  text: string
  /** The open card, or undefined when the map shows the whole tree. */
  card?: OpenCard
  /** The id the previous turn of this conversation named, null when no card was open, undefined before the first turn. */
  previous?: string | null
  /** The paths of the images, in token order: the first is [Image #1]. */
  images?: string[]
  /** The home card of the tab, on its first turn only. */
  home?: OpenCard
}

const named = (card: OpenCard) => (card.title === undefined ? `#${card.id}` : `#${card.id} — ${card.title}`)

export function cardLine(card: OpenCard | undefined, previous: string | null | undefined): string {
  if (!card) return '[no card is open: the map shows the whole tree]'
  return previous === card.id ? `[still on ${named(card)}]` : `[the map is now at ${named(card)}]`
}

export const homeLine = (home: OpenCard): string => `[this conversation is a new tab, and its home card is ${named(home)}]`

export function turnText({ text, card, previous, images = [], home }: TurnInput): string {
  const lines = [cardLine(card, previous)]
  if (home) lines.push(homeLine(home))
  if (images.length > 0) {
    lines.push(...images.map((path, i) => `[Image #${i + 1}] = ${path}`), '', 'Open each image above with Read before you answer.')
  }
  return [...lines, '', text].join('\n')
}
