/**
 * The follow-up tickets a red held-out run files (#st-g2-heldout, #st-build-run-followup): one
 * per ticket whose steps went red, with that ticket's cites, touches and checks, and a brief
 * that quotes each red step word for word. A step an open follow-up covers files nothing.
 */
export function followUpTickets(input: FollowUpInput): FollowUp[] {
  const groups = new Map<number, Step[]>()
  for (const step of input.red) {
    if (input.covered.has(step.id)) continue
    groups.set(step.ticket, [...(groups.get(step.ticket) ?? []), step])
  }
  let next = Math.max(0, ...input.tickets.map((t) => t.number)) + 1
  return [...groups].map(([number, red]) => {
    const source = input.tickets.find((t) => t.number === number)
    const paths = red.length === 1 ? 'a failed user path' : `${red.length} failed user paths`
    const brief = [
      '## What to build',
      `After the merge of ticket ${input.after}, the held-out set found ${paths} of ticket ${number} red on the main line. ` +
        'Make the product do what each step says. Each step, word for word:',
      red.map((s) => s.text).join('\n\n'),
      '## Acceptance criteria',
      red.map((s) => `- [ ] Step ${s.id} works from start to end.`).join('\n'),
    ].join('\n\n')
    const fields: TicketFields = {
      number: next++,
      title: `Make ${paths} work`,
      cites: source?.cites ?? [],
      blockedBy: [],
      stories: [],
      touches: source?.touches ?? [],
      checks: source?.checks ?? [],
      brief,
      root: input.root,
    }
    return { fields, steps: red.map((s) => s.id) }
  })
}
