/**
 * The conversations of a project, folded from the conversations log (#werk-mc-recall,
 * #werk-mc-shared-convo-log). Each line of the log is one session that a tab's agent reported.
 * A pure fold: it lists the conversations, resolves a reference to one of them, and prints the
 * spoken messages of its transcript (#werk-mc-shared).
 */
import type { Message } from '../map/transcript.ts'

/** One line of the conversations log: a session that a tab's agent reported. */
export type ConvoEntry = { tab: string; session: string; home?: string; parent?: string }

export type Convo = ConvoEntry

export type ResolvedConvo = { ok: true; convo: Convo } | { ok: false; error: string }

const isEntry = (e: unknown): e is ConvoEntry =>
  typeof (e as ConvoEntry | null)?.tab === 'string' && typeof (e as ConvoEntry).session === 'string'

/** One conversation per session, in the order the sessions first appeared. A later line for a session replaces the earlier one. */
export function convosOf(entries: readonly unknown[]): Convo[] {
  const bySession = new Map<string, Convo>()
  for (const e of entries) {
    if (!isEntry(e)) continue
    bySession.set(e.session, {
      tab: e.tab,
      session: e.session,
      ...(typeof e.home === 'string' && { home: e.home }),
      ...(typeof e.parent === 'string' && { parent: e.parent }),
    })
  }
  return [...bySession.values()]
}

const homeLabel = (c: Convo) => (c.home === undefined ? '(no home card)' : `#${c.home}`)

/** One line per conversation: its tab, its home card, its session id, and the session it forked from. */
export function convoLines(convos: readonly Convo[]): string[] {
  if (convos.length === 0) return ['no conversation has reported a session yet']
  const tabWidth = Math.max(...convos.map((c) => c.tab.length))
  const homeWidth = Math.max(...convos.map((c) => homeLabel(c).length))
  return convos.map((c) =>
    [c.tab.padEnd(tabWidth), homeLabel(c).padEnd(homeWidth), c.session, ...(c.parent === undefined ? [] : [`forked from ${c.parent}`])].join('  '),
  )
}

/**
 * The conversation a reference names: an exact session id, then a home card with or without
 * its hash, then a tab name, then a session id prefix. The first kind that matches decides. A
 * reference that matches two conversations of that kind is ambiguous, never a guess.
 */
export function resolveConvo(convos: readonly Convo[], ref: string): ResolvedConvo {
  const card = ref.replace(/^#/, '')
  const kinds: ((c: Convo) => boolean)[] = [
    (c) => c.session === ref,
    (c) => c.home !== undefined && c.home === card,
    (c) => c.tab === ref,
    (c) => ref !== '' && c.session.startsWith(ref),
  ]
  for (const matches of kinds) {
    const found = convos.filter(matches)
    if (found.length === 1) return { ok: true, convo: found[0]! }
    if (found.length > 1) {
      return { ok: false, error: `"${ref}" matches ${found.length} conversations: ${found.map((c) => c.session).join(', ')}. Give a session id.` }
    }
  }
  return { ok: false, error: `no conversation "${ref}". werk convos lists them.` }
}

