 * It exits 0 when the checks go green, and 1 when the retry cap stops the loop. Every time
 * limit is a flag, in milliseconds (#st-build-seam).
 */
import { parseArgs } from '../args.ts'
import { registry } from '../registry.ts'
import { buildTicket, DEFAULT_CAP } from '../../build/loop.ts'
import { GitError, repoRoot } from '../../build/worktree.ts'
import { logPath } from '../../map/log.ts'

const USAGE =
  'usage: werk build <ticket-number> [--cap <passes>] [--main <branch>] [--agent-timeout <ms>] [--check-timeout <ms>]\n' +
  '       [--silence-limit <ms>] [--loop-every <ms>] [--classifier-timeout <ms>]'

const DEFAULTS = {
  cap: DEFAULT_CAP,
  'agent-timeout': 30 * 60_000,
  'check-timeout': 10 * 60_000,
  // The overseer (#lp-overseer): 60 seconds of silence, a loop check every 5 minutes.
  'silence-limit': 60_000,
  'loop-every': 5 * 60_000,
  'classifier-timeout': 2 * 60_000,
}

registry.register({
  name: 'build',
  summary: 'build one ready ticket in fresh passes until its checks pass or the retry cap stops it',
  async run(args, io) {
    const usage = (problem: string) => {
      io.err(`werk build: ${problem}`)
      io.err(USAGE)
      return 2
    }
    const parsed = parseArgs(args, ['main', ...Object.keys(DEFAULTS)])
    if (!parsed.ok) return usage(parsed.error)
    if (parsed.positional.length !== 1 || !/^\d+$/.test(parsed.positional[0]!)) return usage('needs exactly one ticket number')
    const numbers: Record<keyof typeof DEFAULTS, number> = { ...DEFAULTS }
    for (const name of Object.keys(DEFAULTS) as (keyof typeof DEFAULTS)[]) {
      const value = parsed.flags.get(name)
      if (value === undefined) continue
      if (!/^\d+$/.test(value) || Number(value) < 1) return usage(`--${name} needs a whole number of 1 or more`)
      numbers[name] = Number(value)
    }

    try {
      const outcome = await buildTicket(
        {
          log: logPath(),
          repo: repoRoot(process.cwd()),
          ticket: Number(parsed.positional[0]),
          main: parsed.flags.get('main') ?? 'main',
          cap: numbers.cap,
          agentTimeoutMs: numbers['agent-timeout'],
          checkTimeoutMs: numbers['check-timeout'],
          overseer: {
            silenceMs: numbers['silence-limit'],
            loopEveryMs: numbers['loop-every'],
            classifierTimeoutMs: numbers['classifier-timeout'],
          },
        },
        io,
      )
      if ('error' in outcome) {
        io.err(`werk build: ${outcome.error}`)
        return 1
      }
      return outcome.green ? 0 : 1
    } catch (err) {
      if (!(err instanceof GitError)) throw err
      io.err(`werk build: ${err.message}`)
      return 1
    }
  },
})
