/**
 * The role of every agent that werk starts (#st-build-seam-role-env). werk names it in the
 * environment of the agent process, in production and in tests alike. The real agent ignores
 * it. The fake agent reads it to pick the reply that a test scripted for the role, and to live
 * as long as the agent it stands in for (#werk-chat-fake-role).
 *
 * A new kind of agent adds one entry here.
 */

/** The environment variable that names the role of an agent process. */
export const ROLE_ENV = 'WERK_AGENT_ROLE'

/**
 * How long an agent lives. A conversation answers one message after another until its input
 * closes (#werk-onechat). A pass reads one message, does one unit of work and exits (#lp-stateless).
 */
export type Lifetime = 'conversation' | 'pass'

export type AgentRole = { name: string; lifetime: Lifetime }

export const ROLES = {
  chat: { name: 'chat', lifetime: 'conversation' },
  specWriter: { name: 'spec-writer', lifetime: 'pass' },
  ticketWriter: { name: 'ticket-writer', lifetime: 'pass' },
  builder: { name: 'builder', lifetime: 'pass' },
  grader: { name: 'grader', lifetime: 'pass' },
  reviewer: { name: 'reviewer', lifetime: 'pass' },
  classifier: { name: 'loop-classifier', lifetime: 'pass' },
  stepAuthor: { name: 'heldout-author', lifetime: 'pass' },
  binder: { name: 'heldout-binder', lifetime: 'pass' },
} as const satisfies Record<string, AgentRole>

/** The role name of the reviewer of one quality area, so a test can script each area its own reply. */
export const reviewerRole = (area: string): string => `${ROLES.reviewer.name}-${area}`

/** The environment entry that names the role of an agent process. */
export const roleEnv = (name: string): Record<string, string> => ({ [ROLE_ENV]: name })

/** The entry of a role name: its own entry, or the entry it is an area of. Undefined for any other name. */
export function roleOf(name: string | undefined): AgentRole | undefined {
  if (name === undefined) return undefined
  return Object.values(ROLES).find((role) => name === role.name || name.startsWith(`${role.name}-`))
}

/** How long an agent of the role lives. A launch with no known role is one pass. */
export const lifetimeOf = (name: string | undefined): Lifetime => roleOf(name)?.lifetime ?? 'pass'
  // A name that only starts with a role name is not that role.
  expect(roleOf('chatty')).toBeUndefined()
