import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { parseArgs } from '../args.ts'
import { registry } from '../registry.ts'
import { fold } from '../../map/fold.ts'
import { logPath, readLog } from '../../map/log.ts'
import { decidedCardsUnder } from '../../map/subtree.ts'
import { checkTickets } from '../../ticket/check.ts'
import { failureLine } from '../../ticket/failure.ts'
import { specStories } from '../../ticket/spec.ts'

const USAGE = 'usage: werk ticket-check <folder> --root <card-id> --spec <spec-file>'

registry.register({
  name: 'ticket-check',
  summary: 'run the own checks and the set checks on a folder of ticket files',
  run(args, io) {
    const usage = (problem: string) => {
      io.err(`werk ticket-check: ${problem}`)
      io.err(USAGE)
      return 2
    }
    const parsed = parseArgs(args, ['root', 'spec'])
    if (!parsed.ok) return usage(parsed.error)
    if (parsed.positional.length !== 1) return usage('needs exactly one folder')
    const root = parsed.flags.get('root')
    const specFile = parsed.flags.get('spec')
    if (root === undefined) return usage('--root is required')
    if (specFile === undefined) return usage('--spec is required')

    // The flags are well formed from here. A thing they name that is not there still stops the call
    // before any check runs, so it exits 2 and never reads as a failed check. It prints no usage,
    // because the form of the call was right.
    const missing = (problem: string) => {
      io.err(`werk ticket-check: ${problem}`)
      return 2
    }
    const folder = parsed.positional[0]!
    if (!existsSync(folder) || !statSync(folder).isDirectory()) return missing(`no folder "${folder}"`)
    if (!existsSync(specFile)) return missing(`no spec file "${specFile}"`)
    const spec = specStories(readFileSync(specFile, 'utf8'))
    if (!spec.ok) return missing(`${specFile}: ${spec.error}`)
    const decided = decidedCardsUnder(fold(readLog(logPath())), root)
    if (!decided) return missing(`no node "${root}"`)

    const files = readdirSync(folder, { withFileTypes: true })
      .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
      .map((entry) => entry.name)
      .toSorted()
      .map((name) => ({ name, text: readFileSync(join(folder, name), 'utf8') }))
    const { passed, failures } = checkTickets(files, decided, spec.stories)

    for (const f of failures) io.out(failureLine(f))
    const failedOwn = files.length - passed.length
    io.out(
      `ticket-check: ${files.length} ticket(s), ${failedOwn} failed their own checks, ` +
        `${failures.length} failure(s) in all, against ${decided.length} decided card(s) and ${spec.stories.length} story(ies)`,
    )
    return failures.length === 0 ? 0 : 1
  },
})
