/** The tabs with the chip `by` places along focused. A step past either end wraps to the other end. */
export function stepped(tabs: Tabs, by: number): Tabs {
  const n = tabs.list.length
  const from = tabs.list.findIndex((t) => t.id === tabs.active)
  return focused(tabs, tabs.list[(((from + by) % n) + n) % n]!.id)
}

/** The fields of a key press that the tab keys read. */
export type TabKeyEvent = { key: string; metaKey: boolean; ctrlKey: boolean; altKey: boolean; shiftKey: boolean }

/** The switch a key press asks for: Cmd+1 to Cmd+5 a position, Cmd+[ and Cmd+] a step. Any other key asks for none. */
export function tabKey(e: TabKeyEvent): { position: number } | { step: number } | undefined {
  if (!e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return undefined
  if (/^[1-5]$/.test(e.key)) return { position: Number(e.key) }
  if (e.key === '[') return { step: -1 }
  if (e.key === ']') return { step: 1 }
  return undefined
}

