export const reviewers: Gate = async (ctx) => {
  const diff = await diffFor(ctx)
  const answers = await Promise.all(
    REVIEW_AREAS.map(async (area) => {
      const out = await ctx.session(`review-${area.key}-${ctx.pass}`, reviewPrompt(area, ctx.base, diff), JUDGE_TOOLS, { role: 'reviewer', onlyTools: true })
