  let failure: Failure | undefined
  if (blocking.length) failure = { kind: 'review', findings: blocking }
  else if (broken.length) failure = { kind: 'step', step: `review (${broken.map((a) => a.area).join(', ')})`, detail: broken.map((a) => a.error).join('; ') }
