/** "> 80%", "< 0.8", "> 100 ms": the direction and the number of a threshold. */
function parseThreshold(s) {
  const m = /([<>])\s*=?\s*([\d.]+)/.exec(s ?? '')
  return m ? { dir: m[1], value: parseFloat(m[2]) } : null
