const m=new Map();for(const r of rs)for(const f of r.failed){const k=f.name;const x=m.get(k)??{n:0,t:0,msg:""};x.n++;if(f.timeout)x.t++;x.msg=f.message;m.set(k,x)}
console.log("runs",rs.length);for(const [k,v] of m)console.log(v.n,"fails",v.t,"timeouts |",k,"|",v.msg.slice(0,90))'
